const unbound=createLearnRuntimeComposition();const commands=new CommandRegistry();bindLearnSurface({commands,learn:unbound.learn,structured:unbound.structured});assert.equal(unbound.descriptor.realConsumer,false);assert.equal(unbound.structured.sourceBinding.truth,'UNAVAILABLE_PROVIDER_UNBOUND');assert.equal(commands.availability('learn.edit',{blockId:'learn-unavailable-p1',patch:{html:'x'}}).enabled,false);assert.equal(commands.availability('learn.practice',{}).enabled,false);
assert.throws(()=>createLearnRuntimeComposition({source:{classification:'SYNTHETIC_DEMO',truth:'DEMO',activity:{id:'x',revision:'r1'},document:{id:'d',revision:'r1',blocks:[]}}}),/LEARN_FIXTURE_OR_SYNTHETIC_SOURCE_FORBIDDEN/);
const records=[{sourceId:'S',revision:'r1',digest:'d1',locator:'rq://S/r1',schemaVersion:'rq-source/1',comparable:{title:{label:'Title',type:'text',value:'A'}}},{sourceId:'S',revision:'r2',digest:'d2',locator:'rq://S/r2',schemaVersion:'rq-source/1',comparable:{title:{label:'Title',type:'text',value:'B'}}}];const rq=new RQDomainAdapter(records);const r=new CommandRegistry();bindRqSurface({commands:r,adapter:rq});const exact={sourceId:'S',revision:'missing',digest:'dm',locator:'rq://S/missing'};const good={sourceId:'S',revision:'r1',digest:'d1',locator:'rq://S/r1'};const av=r.availability('rq.compare',{left:good,right:exact,workingAnalysisId:'x',scope:['claims']});assert.equal(av.enabled,false);assert.equal(av.code,'RQ_COMPARE_RIGHT_MISSING');const ok=r.availability('rq.compare',{left:good,right:{sourceId:'S',revision:'r2',digest:'d2',locator:'rq://S/r2'},workingAnalysisId:'x',scope:['claims']});assert.equal(ok.enabled,true);console.log('CG3_CONTROLLER_CORR01_LEARN_RQ_TRUTH: PASS');
